system_a_kql:
let baselineWindow = 1d;
let spikeWindow = 5m;
let thresholdMultiplier = 5;
NetworkSession
| where NetworkApplicationProtocol == "SMB"
| summarize BaselineCount = count() by SrcDvcId, bin(TimeGenerated, baselineWindow)
| join kind=inner (
    NetworkSession
    | where NetworkApplicationProtocol == "SMB"
    | summarize SpikeCount = count() by SrcDvcId, bin(TimeGenerated, spikeWindow)
) on SrcDvcId
| where SpikeCount > BaselineCount * thresholdMultiplier
| project SrcDvcId, BaselineCount, SpikeCount, TimeGenerated=bin(TimeGenerated, spikeWindow)

