system_a_kql:
let BaselineStart = ago(15d);
let BaselineEnd = ago(1d);
let RecentStart = ago(1d);
let RecentEnd = now();
let PrivateIpRange = (ip: string) {
    // RFC1918 private IP ranges
    (ip matches regex @"^10\.")
    or (ip matches regex @"^172\.(1[6-9]|2[0-9]|3[0-1])\.")
    or (ip matches regex @"^192\.168\.")
};
let SmbPorts = dynamic([139, 445]);
// Baseline: average connection count per SrcIpAddr and SrcPortNumber over 14 days (ending 1 day ago)
let Baseline = network_session
| where TimeGenerated between (BaselineStart .. BaselineEnd)
| where SrcPortNumber in (SmbPorts)
| where PrivateIpRange(SrcIpAddr)
| summarize BaselineCount = count() by SrcIpAddr, SrcPortNumber;
// Recent: connection count per SrcIpAddr and SrcPortNumber in last 1 day
let Recent = network_session
| where TimeGenerated between (RecentStart .. RecentEnd)
| where SrcPortNumber in (SmbPorts)
| where PrivateIpRange(SrcIpAddr)
| summarize RecentCount = count() by SrcIpAddr, SrcPortNumber;
// Join and filter where recent count exceeds baseline by more than 50
Recent
| join kind=inner Baseline on SrcIpAddr, SrcPortNumber
| where RecentCount > BaselineCount + 50
| project SrcIpAddr, SrcPortNumber, BaselineCount, RecentCount

